import org.jetbrains.uast.ULayoutElement;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.List;

import static com.android.tools.lint.detector.api.Scope.RESOURCE_FILE_SCOPE;

/**
 * Detector for inefficient layout weight usage.
 */
public class InefficientWeightDetector extends LayoutDetector {

    private static final Implementation IMPLEMENTATION = new Implementation(
            InefficientWeightDetector.class,
            RESOURCE_FILE_SCOPE);

    /**
     * Layouts that use weights inappropriately are inefficient. This can happen when
     * a {@code LinearLayout} uses the weight attribute, but some of its children
     * also use the weight attribute. This can lead to unnecessary calculations.
     */
    public static final Issue ISSUE = Issue.create(
            "InefficientWeight",
            "Inefficient layout weight usage",
            "Using the weight attribute on children of a LinearLayout that also uses weight " +
                    "can lead to unnecessary computations. It's more efficient to declare " +
                    "weights only on the direct children of the LinearLayout.",
            Category.PERFORMANCE,
            5,
            Severity.WARNING,
            IMPLEMENTATION
    ).addMoreInfo(
            "https://developer.android.com/training/improving-layouts/index.html#weight"
    );


    @Override
    public Collection<Class<? extends UElement>> getApplicableUastTypes() {
        return Arrays.asList(ULayoutElement.class);
    }

    @Override
    public UElementHandler createUastHandler(@NonNull DetectorContext context) {
        return new UElementHandler() {
            @Override
            public void visitLayoutElement(@NonNull ULayoutElement element) {
                // Check if it's a LinearLayout with weight
                if (!element.isViewClass("android.widget.LinearLayout")) {
                    return;
                }

                Boolean hasWeight = element.getAttribute("android:layout_weight") != null;
                if (!hasWeight) {
                    return;
                }

                // Now check its children
                for (UElement child : element.getChildren()) {
                    if (child instanceof ULayoutElement) {
                        ULayoutElement childElement = (ULayoutElement) child;
                        // Check if child is also a LinearLayout or has weight
                        if (childElement.isViewClass("android.widget.LinearLayout") || childElement.getAttribute("android:layout_weight") != null) {
                            // This is a potential inefficiency
                            // We need to ensure the child's weight is non-zero for it to be a true problem
                            // Or if the child is a LinearLayout, we recursively check its children for weight
                            if (childElement.getAttribute("android:layout_weight") != null) {
                                context.report(ISSUE, element, context.getLocation(childElement),
                                        "LinearLayout child also uses weight attribute");
                            } else if (childElement.isViewClass("android.widget.LinearLayout")) {
                                // Recursively check children of this nested LinearLayout
                                checkNestedLinearLayoutChildren(context, childElement);
                            }
                        }
                    }
                }
            }
        };
    }

    private void checkNestedLinearLayoutChildren(@NonNull DetectorContext context, @NonNull ULayoutElement parentLinearLayout) {
        for (UElement child : parentLinearLayout.getChildren()) {
            if (child instanceof ULayoutElement) {
                ULayoutElement childElement = (ULayoutElement) child;
                if (childElement.getAttribute("android:layout_weight") != null) {
                    context.report(ISSUE, parentLinearLayout, context.getLocation(childElement),
                            "Nested LinearLayout child uses weight attribute");
                    return; // Found one, no need to check further for this parent
                }
            }
        }
    }
}
