import com.android.tools.lint.detector.api.SourceCodeScanner;
import com.intellij.psi.PsiClass;
import java.util.Collections;
import java.util.List;
import org.jetbrains.uast.UAnonymousClass;
import org.jetbrains.uast.UClass;

public class HandlerDetector extends Detector implements SourceCodeScanner {

    private static final Implementation IMPLEMENTATION =
            new Implementation(HandlerDetector.class, Scope.JAVA_FILE_SCOPE);

    public static final Issue ISSUE =
            Issue.create(
                    "HandlerLeak",
                    "Handler reference",
                    "Detects memory leaks caused by non-static inner classes that use a `Handler`.",
                    Category.CORRECTNESS,
                    6,
                    Severity.WARNING,
                    IMPLEMENTATION);

    @Override
    public List<String> getApplicableUastTypes() {
        return Collections.singletonList("android.os.Handler");
    }

    @Override
    public void visitClass(JavaContext context, UClass declaration) {
        if (!context.getEvaluator().isStatic(declaration) && declaration.getContainingClass() != null) {
            Location location;
            if (declaration instanceof UAnonymousClass) {
                location = context.getLocation(declaration);
            } else {
                location = context.getNameLocation(declaration);
            }
            String message = "This Handler class should be static or leaks might occur (non-static inner classes hold implicit references to their outer class).";
            context.report(ISSUE, declaration, location, message);
        }
    }
}
